	,copyFrom: function(controls,device) {
		var h = controls.byName.h;
		var _g_keys = Object.keys(h);
		var _g_length = _g_keys.length;
		var _g_current = 0;
		while(_g_current < _g_length) {
			var key = _g_keys[_g_current++];
			var _g = 0;
			var _g1 = h[key].inputs;
			while(_g < _g1.length) {
				var input = _g1[_g];
				++_g;
				if(device == null || funkin_backend_system_Controls.isDevice(input,device)) {
					this.byName.h[key].add(input);
				}
			}
		}
		if(device == null) {
			var _g = 0;
			var _g1 = controls.gamepadsAdded;
			while(_g < _g1.length) {
				var gamepad = _g1[_g];
				++_g;
				var array = this.gamepadsAdded;
				if(array.indexOf(gamepad) == -1) {
					array.push(gamepad);
				}
			}
			this.mergeKeyboardScheme(controls.keyboardScheme);
		} else {
			switch(device._hx_index) {
			case 0:
				this.mergeKeyboardScheme(controls.keyboardScheme);
				break;
			case 1:
				this.gamepadsAdded.push(device.id);
				break;
			}
		}
	}
