	,getInputsFor: function(control,device,list) {
		if(list == null) {
			list = [];
		}
		switch(device._hx_index) {
		case 0:
			var _g = 0;
			var _g1 = this.getActionFromControl(control).inputs;
			while(_g < _g1.length) {
				var input = _g1[_g];
				++_g;
				if(input.device == flixel_input_actions_FlxInputDevice.KEYBOARD) {
					list.push(input.inputID);
				}
			}
			break;
		case 1:
			var _g = device.id;
			var _g1 = 0;
			var _g2 = this.getActionFromControl(control).inputs;
			while(_g1 < _g2.length) {
				var input = _g2[_g1];
				++_g1;
				if(input.deviceID == _g) {
					list.push(input.inputID);
				}
			}
			break;
		}
		return list;
	}
	,removeDevice: function(device) {
		switch(device._hx_index) {
		case 0:
			this.setKeyboardScheme(funkin_backend_system_KeyboardScheme.None);
			break;
		case 1:
			this.removeGamepad(device.id);
			break;
		}
	}
	,mobileControlsJustPressed: function(id) {
		var state = funkin_backend_MusicBeatState.getState();
		var substate = funkin_backend_MusicBeatSubstate.instance;
		var bools = [false,false,false,false];
		if(state != null) {
			if(state.touchPad != null) {
				bools[0] = state.touchPad.checkButtonArrayState([id],mobile_funkin_backend_system_input_ButtonsStates.JUST_PRESSED);
			}
			if(state.mobileControls != null) {
				bools[1] = state.mobileControls.instance.checkButtonArrayState([id],mobile_funkin_backend_system_input_ButtonsStates.JUST_PRESSED);
			}
		}
		if(substate != null) {
			if(substate.touchPad != null) {
				bools[2] = substate.touchPad.checkButtonArrayState([id],mobile_funkin_backend_system_input_ButtonsStates.JUST_PRESSED);
			}
			if(substate.mobileControls != null) {
				bools[3] = substate.mobileControls.instance.checkButtonArrayState([id],mobile_funkin_backend_system_input_ButtonsStates.JUST_PRESSED);
			}
		}
		return bools.indexOf(true) != -1;
	}
